package variant;
import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.io.*;import java.util.*;import java.util.stream.*;
public class Example {
private static void create(Path out)throws IOException {File parent=out.toAbsolutePath().getParent().toFile();if(!parent.exists()&&!parent.mkdirs())throw new IOException("Не создан каталог "+parent);File f=out.toFile();if(!f.exists()&&!f.createNewFile())throw new IOException("Не создан файл "+f);}
public String clean(String text){var out=new StringBuilder();int state=0;boolean escaped=false;for(int i=0;i<text.length();i++){char c=text.charAt(i),next=i+1<text.length()?text.charAt(i+1):0;if(state==0){if(c=='"'){state=1;out.append(c);}else if(c=='\''){state=2;out.append(c);}else if(c=='/'&&next=='/'){state=3;i++;}else if(c=='/'&&next=='*'){state=4;i++;out.append(' ');}else out.append(c);}else if(state==1||state==2){out.append(c);if(escaped)escaped=false;else if(c=='\\')escaped=true;else if(state==1&&c=='"'||state==2&&c=='\'')state=0;}else if(state==3){if(c=='\r'||c=='\n'){out.append(c);state=0;}}else{if(c=='*'&&next=='/'){state=0;i++;}else if(c=='\r'||c=='\n')out.append(c);}}return out.toString();}public void process(Path in,Path out)throws IOException{String result=clean(Files.readString(in,StandardCharsets.UTF_8));create(out);Files.writeString(out,result,StandardCharsets.UTF_8);}
}
